style.css:
@-moz-document domain("yandex.ru"), domain("ya.ru") {
/* Фон Яндекс Браузера */
    body {
        background-image: url("https://images.unsplash.com/photo-1513360371669-4adf3dd7dff8") !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* Розовая строка поиска */
    input,
    input[type="text"],
    .search3__input,
    .mini-suggest__input {
        background: #ffcce4 !important;
        color: #b64d83 !important;
        border: 2px solid #f48fbd !important;
        border-radius: 25px !important;
        box-shadow: 0 0 12px #ff9ecb !important;
    }

    /* Текст внутри поиска */
    input::placeholder {
        color: #c76c9c !important;
    }

    /* Кнопки */
    button {
        background: #f5a4ca !important;
        color: white !important;
        border-radius: 20px !important;
        border: none !important;
    }
}
